class Rectangle {
    private int w, h;
    public Rectangle(int w, int h) { this.w = w; this.h = h; }
    public void scale(int k) { w *= k; h *= k; }
    public Rectangle scaled(int k) { return new Rectangle(w * k, h * k); }
    public int area() { return w * h; }
}
```

```java
